export function normalizeRsvpNumberLexeme(value: string): string | null {
  const match = /^([+-]?)(?:(\d+)(?:[.]([0-9]*))?|[.]([0-9]+))(?:[eE]([+-]?[0-9]+))?$/.exec(value)
  if (!match) return null
  const sign = match[1] === '-' ? '-' : ''
  const integer = (match[2] ?? '0').replace(/^0+(?=[0-9])/, '')
  const fraction = match[3] ?? match[4] ?? ''
  const exponent = match[5] === undefined ? '' : `e${match[5]}`
  return `${sign}${integer}${fraction ? `.${fraction}` : ''}${exponent}`
}
/** Preserve number-input decimal lexemes as JSON number tokens without a JS Number round-trip. */
function serializePublicRsvpRequest(request: SubmitPublicRsvpRequest): string {
  const answers = request.answers.map(answer => {
    const fields = Object.entries(answer).filter(([, value]) => value !== undefined).map(([key, value]) => {
      if (key === 'numberValue' && typeof value === 'string') {
        const normalized = normalizeRsvpNumberLexeme(value)
        if (normalized === null) {
          throw new TypeError('RSVP number answers must be valid decimal JSON number lexemes.')
        }
        return `${JSON.stringify(key)}:${normalized}`
      }
      return `${JSON.stringify(key)}:${JSON.stringify(value)}`
    })
    return `{${fields.join(',')}}`
  })
  return `{"answers":[${answers.join(',')}]}`
}
