  public constructor(options: ApiClientOptions = {}) {
    this.baseUrl = (options.baseUrl ?? '').replace(/\/$/, '')
    this.request = options.fetch ?? globalThis.fetch.bind(globalThis)
  }

  public async getSystemInfo(signal?: AbortSignal): Promise<SystemInfo> {
    const response = await this.request(`${this.baseUrl}/api/v1/system/info`, {
      credentials: 'include',
      signal,
    })

    if (!response.ok) {
      throw new Error(`API request failed with status ${response.status}.`)
    }

    return (await response.json()) as SystemInfo
  }

  public async getSessionAccess(signal?: AbortSignal): Promise<SessionAccessSnapshot> {
    const response = await this.request(`${this.baseUrl}/api/v1/auth/session`, {
      credentials: 'include',
      cache: 'no-store',
      signal,
    })

    if (!response.ok) {
      throw new Error(`API request failed with status ${response.status}.`)
    }

    return (await response.json()) as SessionAccessSnapshot
  }

