  public async uploadPublicMemoryMedia(intent: PublicMemoryUploadIntent, file: File, onProgress?: (loaded: number, total: number) => void): Promise<void> {
    await new Promise<void>((resolve, reject) => {
      const request = new XMLHttpRequest()
      request.open('PUT', intent.ingressUri)
      request.withCredentials = false
      for (const [name, value] of Object.entries(intent.ingressHeaders)) request.setRequestHeader(name, value)
      request.upload.onprogress = event => { if (event.lengthComputable) onProgress?.(event.loaded, event.total) }
      request.onload = () => request.status >= 200 && request.status < 300
        ? resolve()
        : reject(new Error('Guest media upload failed.'))
      request.onerror = () => reject(new Error('Guest media upload failed.'))
      request.onabort = () => reject(new DOMException('Upload aborted.', 'AbortError'))
      request.send(file)
    })
  }

